function ways(n) {
  if (n <= 2) {
    return n;
  }
  var prev = 1;
  var current = 2;
  for (var i = 3; i <= n; i++) {
    var next = prev + current;
    prev = current;
    current = next;
  }
  return current;
}

console.log(ways(25));
